final showHint = useState(false);
final hintFaded = useState(false);

final isLinux = Platform.isLinux;
final seekCrumbText = useMemoized(() => ValueNotifier<String?>(null));
final seekClearTimer = useRef<Timer?>(null);
useEffect(() => seekCrumbText.dispose, [seekCrumbText]);

// Formats the live swipe-to-seek preview that (on Linux) replaces the
// bottom folder-path crumb while dragging.
String formatSeekCrumb(Duration target, Duration duration, double fraction) {
  if (duration.inMilliseconds <= 0) {
    return '--:-- / --:-- · 0%';
  }
  final pct = (fraction * 100).round().clamp(0, 100);
  return '${formatClock(target.inMilliseconds)} / ${formatClock(duration.inMilliseconds)} · ${pct}%';
}

void setSeekCrumb(Duration target, Duration duration, double fraction) {
  if (!isLinux) return;
  seekClearTimer.value?.cancel();
  seekClearTimer.value = null;
  seekCrumbText.value = formatSeekCrumb(target, duration, fraction);
}

void clearSeekCrumbSoon() {
  if (!isLinux) return;
  seekClearTimer.value?.cancel();
  // Keep a brief post-release window so screenshot capture can observe
  // the final scrubbing position; clears immediately on the next drag.
  seekClearTimer.value = Timer(const Duration(milliseconds: 150), () {
    seekCrumbText.value = null;
  });
}

final swipeUpAccum = useRef<double>(0);

